"use strict";(self.webpackChunk_iehr_web=self.webpackChunk_iehr_web||[]).push([[9991],{7723:(e,i,t)=>{t.r(i),t.d(i,{assets:()=>d,contentTitle:()=>r,default:()=>h,frontMatter:()=>a,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"policies/Media-Sanitization-and-Disposal-Policy","title":"Media Sanitization and Disposal Policy","description":"PURPOSE","source":"@site/docs/policies/Media-Sanitization-and-Disposal-Policy.md","sourceDirName":"policies","slug":"/policies/Media-Sanitization-and-Disposal-Policy","permalink":"/docs/policies/Media-Sanitization-and-Disposal-Policy","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{}}');var o=t(4848),s=t(8453);const a={},r="Media Sanitization and Disposal Policy",d={},l=[{value:"PURPOSE",id:"purpose",level:2},{value:"POLICY",id:"policy",level:2},{value:"DEFINITIONS",id:"definitions",level:2},{value:"PROCEDURE",id:"procedure",level:2},{value:"VIOLATIONS",id:"violations",level:2}];function c(e){const i={h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(i.header,{children:(0,o.jsx)(i.h1,{id:"media-sanitization-and-disposal-policy",children:"Media Sanitization and Disposal Policy"})}),"\n",(0,o.jsx)(i.h2,{id:"purpose",children:"PURPOSE"}),"\n",(0,o.jsx)(i.p,{children:"iEHR is committed to complying with HIPAA Security Rule requirements pertaining to the integrity, confidentiality, and availability of electronic protected health information. iEHR recognizes there are times in which media will need to be destroyed.  This policy has been created to effectively destroy media while adhering to the HIPAA Security rules."}),"\n",(0,o.jsx)(i.h2,{id:"policy",children:"POLICY"}),"\n",(0,o.jsx)(i.p,{children:"iEHR requires that prior to disposal or reuse of hardware or media that contains or previously contained ePHI either the data will be securely overwritten or the device and/or media be physically destroyed and that such steps taken will be documented."}),"\n",(0,o.jsx)(i.h2,{id:"definitions",children:"DEFINITIONS"}),"\n",(0,o.jsxs)(i.ol,{children:["\n",(0,o.jsx)(i.li,{children:"Electronic Protected Health Information (ePHI): individually identifiable health information that is transmitted by electronic media, maintained in electronic media, or transmitted or maintained in any other form or medium."}),"\n",(0,o.jsx)(i.li,{children:"Securely Overwritten: The process of overwriting data with 1 and 0 to render the data irretrievable."}),"\n",(0,o.jsx)(i.li,{children:"Physically Destroyed: The process of physically destroying electronic media to an extent where data is no longer retrievable."}),"\n",(0,o.jsx)(i.li,{children:"Reuse of Hardware: The process of reallocating hardware that contains or may have contained ePHI to an individual that does not have authority to access ePHI."}),"\n",(0,o.jsx)(i.li,{children:"Degauss: Using a magnetic field to erase (neutralize) the data stored on magnetic media."}),"\n",(0,o.jsx)(i.li,{children:"Sanitization:  Removal or the act of overwriting data to a point of preventing the recovery of the data on the device or media that is being sanitized. Sanitization is typically done before re-issuing a device or media, donating equipment that contained sensitive information or returning leased equipment to the lending company."}),"\n"]}),"\n",(0,o.jsx)(i.h2,{id:"procedure",children:"PROCEDURE"}),"\n",(0,o.jsxs)(i.ol,{children:["\n",(0,o.jsxs)(i.li,{children:["All electronic media must be properly sanitized before it is transferred from the current owner. The proper sanitization method depends on the type of media and the intended disposition of the media.  This means that all ePHI on decommissioned devices and storage media must be irretrievably destroyed, in order to protect the confidentiality of the data contained.","\n",(0,o.jsxs)(i.ol,{children:["\n",(0,o.jsx)(i.li,{children:"If the device or media contains ePHI that is not required or needed, and is not a unique copy, a data destruction tool must be used to destroy the data on the device or media prior to disposal. A typical reformat is not sufficient as it does not overwrite the data."}),"\n",(0,o.jsx)(i.li,{children:"If the device or media contains the only copy of ePHI that is required or needed, a retrievable copy of the ePHI must be made prior to disposal."}),"\n"]}),"\n"]}),"\n",(0,o.jsx)(i.li,{children:"All destruction/disposal of patient health information media will be done in accordance with federal and state laws and regulations and pursuant to the organization\u2019s written retention policy/schedule. Records that have satisfied the period of retention will be destroyed/disposed of in an appropriate manner."}),"\n",(0,o.jsx)(i.li,{children:"Records involved in any open investigation, audit or litigation should not be destroyed/disposed of.  If notification is received that any of the above situations have occurred or there is the potential for such, the record retention schedule shall be suspended for these records until such time as the situation has been resolved.  If the records have been requested in the course of a judicial or administrative hearing, a qualified protective order will be obtained to ensure that the records are returned to the organization or properly destroyed/disposed of by the requesting party."}),"\n",(0,o.jsx)(i.li,{children:"Any media containing ePHI should be destroyed/disposed of using a method that ensures the ePHI cannot be recovered.  The methods of destruction, disposal, and reuse should be reassessed periodically, based on current technology, accepted practices, and availability of timely and cost-effective destruction, disposal, and reuse technologies and services."}),"\n",(0,o.jsxs)(i.li,{children:["Before reuse of any recordable and erasable media, all ePHI must be rendered inaccessible, cleaned, or scrubbed.  Any equipment or storage media that contains confidential, critical, and/or private information will be erased by appropriate means or destroyed by the Security Officer or his/her appointed designee before the equipment/media is reused. Methods include:","\n",(0,o.jsxs)(i.ol,{children:["\n",(0,o.jsx)(i.li,{children:'Removable magnetic "disks" (floppies, ZIP disks, and the like) and magnetic tapes (reels, cartridges) can be "degaussed" by an appropriately-sized-and-powered degausser or physically destroyed.'}),"\n",(0,o.jsx)(i.li,{children:"Fixed internal magnetic storage (such as computer hard drives), as well as removable storage, can be cleansed by a re-writing process. Software is used to overwrite all the usable storage locations of a medium. The simplest method is a single overwrite; additional security is provided by multiple overwrites with variations of all 0s, all 1s, complements (opposite of recorded character), and/or random characters."}),"\n",(0,o.jsx)(i.li,{children:'A few kinds of "write-many" optical media (such as CD-RWs) can be processed via an overwrite method. This is not the case for the vast majority of "write-once" optical media in use (notably the CD-R). Write-once media cannot be degaussed, because such media are optical rather than magnetic. Therefore, only physical destruction will do.'}),"\n",(0,o.jsx)(i.li,{children:'Removable "solid state" storage devices are also now available. These "flash memory" devices are solid state and are non-volatile (the memory maintains data even after all power sources have been disconnected). Examples include CompactFlash, Memory Stick, Secure Digital, SmartMedia and other types of plug-ins, and a range of "mini-" and "micro-drive" flash devices that use USB or FireWire ports. Secure overwrites (following manufacturer specifications) are possible for these media as well. Neither degaussing nor over-writing offers absolute guarantees. However, complete destruction is available.'}),"\n"]}),"\n"]}),"\n",(0,o.jsx)(i.li,{children:"All original ePHI must be backed up on a regular basis. Backup mechanisms will be tested regularly to verify that ePHI can be efficiently retrieved. This includes backup of portable devices such as laptops and PDA\u2019s, when storing original ePHI. Backups of original ePHI must be stored off-site in a physically secure facility."}),"\n",(0,o.jsx)(i.li,{children:"Copies of documents and images that contain PHI and are not originals that do not require retention based on retention policies (e.g., provider copies, schedule print outs etc.) shall be destroyed/disposed of by shredding or other acceptable manner as outlined in this policy.  Certification of destruction is not required."}),"\n",(0,o.jsx)(i.li,{children:"Records scheduled for destruction/disposal should be secured against unauthorized or inappropriate access until the destruction/disposal of PHI is complete."}),"\n",(0,o.jsxs)(i.li,{children:["A record of all PHI media sanitization should be made and retained by the organization.  The organization has the responsibility to retain the burden of proof for any media destruction regardless of whether destruction is done by the organization or by a contractor.  Retention is required because the records of destruction/disposal may become necessary to demonstrate that the patient information records were destroyed/disposed of in the regular course of business.  Records of destruction/disposal, such as a certificate of destruction, should include:","\n",(0,o.jsxs)(i.ol,{children:["\n",(0,o.jsx)(i.li,{children:"Date of destruction/disposal."}),"\n",(0,o.jsx)(i.li,{children:"Method of destruction/disposal."}),"\n",(0,o.jsx)(i.li,{children:"Description of the destroyed/disposed record series or medium."}),"\n",(0,o.jsx)(i.li,{children:"Inclusive dates covered."}),"\n",(0,o.jsx)(i.li,{children:"A statement that the patient information records were destroyed/disposed of in the normal course of business."}),"\n",(0,o.jsx)(i.li,{children:"The signatures of the individuals supervising and witnessing the destruction/disposal."}),"\n"]}),"\n"]}),"\n",(0,o.jsxs)(i.li,{children:["If destruction/disposal services are contracted, the contract must provide that the organization\u2019s business associate will establish the permitted and required uses and disclosures of information by the business associate as set forth in the federal and state law (outlined in organization\u2019s HIPAA Business Associated Agreement/Contract).  The BAA should also set minimum acceptable standards for the sanitization of media containing PHI.  The BAA or contract should  include but not be limited to the following:","\n",(0,o.jsxs)(i.ol,{children:["\n",(0,o.jsx)(i.li,{children:"Specify the method of destruction/disposal."}),"\n",(0,o.jsx)(i.li,{children:"Specify the time that will elapse between acquisition and destruction/disposal of data/media."}),"\n",(0,o.jsx)(i.li,{children:"Establish safeguards against unauthorized disclosures of PHI."}),"\n",(0,o.jsx)(i.li,{children:"Indemnify the organization from loss due to unauthorized disclosure."}),"\n",(0,o.jsx)(i.li,{children:"Require that the business associate maintain liability insurance in specified amounts at all times the contract is in effect."}),"\n",(0,o.jsx)(i.li,{children:"Provide proof of destruction/disposal (e.g. certificate of destruction)."}),"\n"]}),"\n"]}),"\n",(0,o.jsxs)(i.li,{children:["The provider, or the personal representative of a deceased health care provider, shall comply with the Federal and State statutes to ensure appropriate preservation, patient notice, and/or destruction/disposal of the patient health care records in the possession of the health care provider at the time the practice was ceased or the provider died.  This statute does not apply to:","\n",(0,o.jsxs)(i.ol,{children:["\n",(0,o.jsxs)(i.li,{children:["\n",(0,o.jsx)(i.p,{children:"Community-based residential facilities or nursing homes."}),"\n"]}),"\n",(0,o.jsxs)(i.li,{children:["\n",(0,o.jsx)(i.p,{children:"Hospitals."}),"\n"]}),"\n",(0,o.jsxs)(i.li,{children:["\n",(0,o.jsx)(i.p,{children:"Hospices."}),"\n"]}),"\n",(0,o.jsxs)(i.li,{children:["\n",(0,o.jsx)(i.p,{children:"Home Health Agencies."}),"\n"]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,o.jsx)(i.h2,{id:"violations",children:"VIOLATIONS"}),"\n",(0,o.jsx)(i.p,{children:"Any individual, found to have violated this policy, may be subject to disciplinary action up to and including termination of employment."})]})}function h(e={}){const{wrapper:i}={...(0,s.R)(),...e.components};return i?(0,o.jsx)(i,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},8453:(e,i,t)=>{t.d(i,{R:()=>a,x:()=>r});var n=t(6540);const o={},s=n.createContext(o);function a(e){const i=n.useContext(s);return n.useMemo((function(){return"function"==typeof e?e(i):{...i,...e}}),[i,e])}function r(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),n.createElement(s.Provider,{value:i},e.children)}}}]);